fn rewrite_profile(
    cwd: &std::path::Path,
    profile: &str,
    rewrite: impl FnOnce(&mut Vec<(Value, Value)>, &ObjectStore),
) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(profile).unwrap()).unwrap()
    else {
        panic!("benchmark profile must be a Value map")
    };
    rewrite(&mut entries, &store);
    put_value(&store, Value::Map(entries))
}

fn put_value(store: &ObjectStore, value: Value) -> String {
    store
        .put_canonical(&encode_value_node(&value).unwrap())
        .unwrap()
}

fn field_mut<'a>(entries: &'a mut [(Value, Value)], name: &str) -> &'a mut Value {
    &mut entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .unwrap()
        .1
}

fn assert_ordered(value: &JsonValue, prefix: &str) {
    let min = value[format!("{prefix}_min")].as_u64().unwrap();
    let median = value[format!("{prefix}_median")].as_u64().unwrap();
    let max = value[format!("{prefix}_max")].as_u64().unwrap();
    assert!(min <= median && median <= max);
}

fn text<'a>(value: &'a JsonValue, field: &str) -> &'a str {
